var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 7\u201314 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a01 09\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0432\u044b\u043f\u0443\u0441\u043a\u0435\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043e\u0442\u043a\u0440\u043e\u0435\u0442 \u2028\u000d\u000a17 \u0442\u044b\u0441. \u043a\u043c\u00b2 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0434\u043b\u044f \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0438 \u000d\u000a\u041a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u0442 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u0430\u043c \u043d\u043e\u0432\u044b\u0435 \u0443\u0447\u0430\u0441\u0442\u043a\u0438 \u000d\u000a\u043f\u043e\u0434 \u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0443 \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0445 \u0438\u0441\u043a\u043e\u043f\u0430\u0435\u043c\u044b\u0445 \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 Vision \u000d\u000a2030. \u041f\u043b\u043e\u0449\u0430\u0434\u044c \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0445 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0439 \u0434\u043e\u0441\u0442\u0438\u0433\u043d\u0435\u0442 \u000d\u000a50 \u0442\u044b\u0441. \u043a\u043c\u00b2 \u043a \u043a\u043e\u043d\u0446\u0443 \u0433\u043e\u0434\u0430. \u041f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u0410\u0440\u0430\u0432\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u0449\u0438\u0442\u0430 \u0443\u0436\u0435 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u2028\u000d\u000a\u0432 $2,5 \u0442\u0440\u043b\u043d.\u000d\u000aMaaden \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430 \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u044c\u043d\u0443\u044e \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u000d\u000a\u043d\u0430 127%\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Maaden \u000d\u000a\u043e\u0442\u0447\u0438\u0442\u0430\u043b\u0430\u0441\u044c \u043e \u0447\u0438\u0441\u0442\u043e\u0439 \u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u0432 $587 \u043c\u043b\u043d \u2028\u000d\u000a\u0437\u0430 III \u043a\u0432\u0430\u0440\u0442\u0430\u043b. \u0420\u043e\u0441\u0442 \u0441\u0432\u044f\u0437\u0430\u043d \u0441 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435\u043c \u043f\u0440\u043e\u0434\u0430\u0436 \u000d\u000a\u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432, \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0438 \u0437\u043e\u043b\u043e\u0442\u0430. \u0421 \u043d\u0430\u0447\u0430\u043b\u0430 \u0433\u043e\u0434\u0430 \u000d\u000a\u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0430\u043a\u0446\u0438\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 50%.\u000d\u000a\u041a\u0430\u043d\u0430\u0434\u0441\u043a\u0430\u044f Aya \u043e\u0446\u0435\u043d\u0438\u043b\u0430 \u043c\u0430\u0440\u043e\u043a\u043a\u0430\u043d\u0441\u043a\u0438\u0439 \u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442 Boumadine \u0432 $3 \u043c\u043b\u0440\u0434\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u2028\u000d\u000a\u042d\u0440 \u0420\u0430\u0448\u0438\u0434\u0438\u044f \u043d\u0435\u0434\u0430\u043b\u0435\u043a\u043e \u043e\u0442 \u0430\u043b\u0436\u0438\u0440\u0441\u043a\u043e\u0439 \u0433\u0440\u0430\u043d\u0438\u0446\u044b \u0448\u0435\u0441\u0442\u044c \u000d\u000a\u043a\u0430\u0440\u044c\u0435\u0440\u043e\u0432 \u0438 \u0442\u0440\u0438 \u0448\u0430\u0445\u0442\u044b \u0441 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u000d\u000a8 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u0440\u0443\u0434\u044b \u0432 \u0441\u0443\u0442\u043a\u0438. \u0421\u0440\u043e\u043a \u043e\u043a\u0443\u043f\u0430\u0435\u043c\u043e\u0441\u0442\u0438 \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u000d\u000a1,2 \u0433\u043e\u0434\u0430 \u043f\u0440\u0438 \u0446\u0435\u043d\u0435 \u0437\u043e\u043b\u043e\u0442\u0430 $4 \u0442\u044b\u0441. \u0437\u0430 \u0443\u043d\u0446\u0438\u044e.\u000d\u000a\u0411\u044e\u0434\u0436\u0435\u0442\u043d\u044b\u0439 \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0441\u044f \u0434\u043e $23,6 \u043c\u043b\u0440\u0434\u000d\u000a\u0414\u043e\u0445\u043e\u0434\u044b \u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u0441\u043d\u0438\u0437\u0438\u043b\u0438\u0441\u044c \u043d\u0430 13% \u0438\u0437 \u0437\u0430 \u043f\u0430\u0434\u0435\u043d\u0438\u044f \u000d\u000a\u043d\u0435\u0444\u0442\u044f\u043d\u044b\u0445 \u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0439, \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u0440\u0430\u0441\u0445\u043e\u0434\u044b \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u000d\u000a\u043d\u0430 6%. \u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432 \u0441\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043b\u043e \u000d\u000a\u0433\u043e\u0434\u043e\u0432\u043e\u0439 \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430 \u0434\u043e $65,3 \u043c\u043b\u0440\u0434.\u000d\u000aDHL \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442 \u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435 \u0430\u0432\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u000d\u000a\u0442\u0435\u0445\u0446\u0435\u043d\u0442\u0440 \u0437\u0430 $85 \u043c\u043b\u043d\u000d\u000a\u041e\u0431\u044a\u0435\u043a\u0442 \u043f\u043b\u043e\u0449\u0430\u0434\u044c\u044e 33,8 \u0442\u044b\u0441. \u043c\u00b2 \u0431\u0443\u0434\u0435\u0442 \u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u0442\u044c \u000d\u000a\u0441\u0430\u043c\u043e\u043b\u0435\u0442\u044b Boeing 777 \u0438 767. \u0426\u0435\u043d\u0442\u0440 \u0441\u0442\u0430\u043d\u0435\u0442 \u043f\u0435\u0440\u0432\u044b\u043c \u0434\u043b\u044f \u000d\u000aDHL \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435 \u0438 \u043d\u0430\u0447\u043d\u0435\u0442 \u0440\u0430\u0431\u043e\u0442\u0443 \u0432 2028 \u0433\u043e\u0434\u0443.\u000d\u000a\u041f\u0435\u0440\u0432\u043e\u0435 \u0441 \u043d\u0430\u0447\u0430\u043b\u0430 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0432 \u0413\u0430\u0437\u0435 \u000d\u000a\u0441\u0432\u0435\u0440\u0445\u043a\u0440\u0443\u043f\u043d\u043e\u0435 \u0441\u0443\u0434\u043d\u043e \u043f\u0440\u043e\u0448\u043b\u043e \u0447\u0435\u0440\u0435\u0437 \u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u000d\u000a\u043a\u0430\u043d\u0430\u043b\u000d\u000a\u041a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043e\u0432\u043e\u0437 Benjamin Franklin \u0441\u0442\u0430\u043b \u043f\u0435\u0440\u0432\u044b\u043c \u0437\u0430 \u0434\u0432\u0430 \u000d\u000a\u0433\u043e\u0434\u0430 \u0441\u0443\u0434\u043d\u043e\u043c \u0442\u0430\u043a\u043e\u0433\u043e \u043a\u043b\u0430\u0441\u0441\u0430, \u043f\u0440\u043e\u0448\u0435\u0434\u0448\u0438\u043c \u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u000d\u000a\u043a\u0430\u043d\u0430\u043b. \u0410\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u043a\u0430\u043d\u0430\u043b\u0430 \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430 \u000d\u000a\u043e \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0438 \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u043d\u044b\u0445 \u0440\u0435\u0439\u0441\u043e\u0432, \u0447\u0442\u043e \u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u000d\u000a\u043d\u0430 \u0441\u0442\u0430\u0431\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438 \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u043c \u043c\u043e\u0440\u0435. \u0415\u0433\u0438\u043f\u0435\u0442 \u000d\u000a\u043f\u043e\u0442\u0435\u0440\u044f\u043b \u043e\u043a\u043e\u043b\u043e $9 \u043c\u043b\u0440\u0434 \u0434\u043e\u0445\u043e\u0434\u043e\u0432 \u043e\u0442 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u044f \u0441\u0443\u0434\u043e\u0432 \u043f\u043e \u000d\u000a\u043a\u0430\u043d\u0430\u043b\u0443 \u0438\u0437 \u0437\u0430 \u0445\u0443\u0441\u0438\u0442\u043e\u0432, \u043d\u043e \u0442\u0435\u043f\u0435\u0440\u044c \u043e\u0436\u0438\u0434\u0430\u0435\u0442 \u000d\u000a\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0442\u0440\u0430\u043d\u0437\u0438\u0442\u0430.\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0441\u043d\u044f\u043b \u0437\u0430\u043f\u0440\u0435\u0442 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0433\u0430\u043b\u043b\u0438\u044f, \u000d\u000a\u0433\u0435\u0440\u043c\u0430\u043d\u0438\u044f \u0438 \u0441\u0443\u0440\u044c\u043c\u044b \u0432 \u0421\u0428\u0410\u000d\u000a\u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043d\u044f\u0442\u043e \u043f\u043e\u0441\u043b\u0435 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u043e\u0432 \u0422\u0440\u0430\u043c\u043f\u0430 \u2028\u000d\u000a\u0438 \u0421\u0438 \u0426\u0437\u0438\u043d\u044c\u043f\u0438\u043d\u0430. \u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0431\u0443\u0434\u0443\u0442 \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b \u000d\u000a\u0434\u043e \u043a\u043e\u043d\u0446\u0430 2026 \u0433\u043e\u0434\u0430. \u041a\u0438\u0442\u0430\u0439 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442 \u0431\u043e\u043b\u0435\u0435 90% \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u0433\u0430\u043b\u043b\u0438\u044f \u0438 60% \u0433\u0435\u0440\u043c\u0430\u043d\u0438\u044f.\u000d\u000a\u041a\u043e\u043d\u0433\u043e \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430 \u0440\u0443\u0434\u043d\u0438\u043a Huayou Cobalt \u0438\u0437\u000d\u000a\u0437\u0430 \u0437\u0430\u0433\u0440\u044f\u0437\u043d\u0435\u043d\u0438\u044f\u000d\u000a\u0420\u0430\u0431\u043e\u0442\u0430 \u043c\u0435\u0434\u043d\u043e \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u043e\u0433\u043e \u043c\u0435\u0441\u0442\u043e\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u000d\u000a\u041b\u0443\u0438\u0441\u0432\u0438\u0448\u0438 \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0430 \u043d\u0430 \u0442\u0440\u0438 \u043c\u0435\u0441\u044f\u0446\u0430. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u043e\u0431\u044f\u0437\u0430\u043d\u0430 \u0443\u0441\u0442\u0440\u0430\u043d\u0438\u0442\u044c \u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u044f \u043f\u0440\u043e\u0440\u044b\u0432\u0430 \u0434\u0430\u043c\u0431\u044b \u000d\u000a\u0438 \u0432\u044b\u043f\u043b\u0430\u0442\u0438\u0442\u044c \u043a\u043e\u043c\u043f\u0435\u043d\u0441\u0430\u0446\u0438\u0438 \u043f\u043e\u0441\u0442\u0440\u0430\u0434\u0430\u0432\u0448\u0438\u043c.\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u043e\u0434\u043e\u0431\u0440\u0438\u043b \u043b\u0438\u0442\u0438\u0435\u0432\u043e\u0435 \u0421\u041f Codelco \u0438 SQM \u000d\u000a\u0432 \u0427\u0438\u043b\u0438\u000d\u000a\u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043f\u0443\u0442\u044c \u043a \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0439 \u0434\u043e\u0431\u044b\u0447\u0435 \u000d\u000a\u043d\u0430 \u0441\u043e\u043b\u043e\u043d\u0447\u0430\u043a\u0435 \u0410\u0442\u0430\u043a\u0430\u043c\u0430. Tianqi Lithium, \u0432\u043b\u0430\u0434\u0435\u044e\u0449\u0430\u044f \u000d\u000a\u0434\u043e\u043b\u0435\u0439 \u0432 SQM, \u043e\u0431\u044f\u0437\u0430\u043d\u0430 \u043f\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u043c \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f\u043c \u043b\u0438\u0442\u0438\u0439 \u043f\u043e \u0440\u044b\u043d\u043e\u0447\u043d\u044b\u043c \u0446\u0435\u043d\u0430\u043c.\u000d\u000a\u0415\u0421 \u0440\u0430\u0441\u0441\u043b\u0435\u0434\u0443\u0435\u0442 \u043f\u043e\u043a\u0443\u043f\u043a\u0443 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 MMG \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u0432 \u0411\u0440\u0430\u0437\u0438\u043b\u0438\u0438\u000d\u000a\u0411\u0440\u044e\u0441\u0441\u0435\u043b\u044c \u043e\u043f\u0430\u0441\u0430\u0435\u0442\u0441\u044f \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u044f \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u000d\u000a\u0444\u0435\u0440\u0440\u043e\u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0415\u0432\u0440\u043e\u043f\u0443 \u043f\u043e\u0441\u043b\u0435 \u0441\u0434\u0435\u043b\u043a\u0438 \u043d\u0430 $500 \u043c\u043b\u043d. \u000d\u000a\u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u0438\u043d\u044f\u0442\u043e \u0434\u043e \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430.","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 7\u201314 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u0442 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u0430\u043c \u2028\u000d\u000a\u043d\u043e\u0432\u044b\u0435 \u0443\u0447\u0430\u0441\u0442\u043a\u0438 \u0434\u043b\u044f \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043a\u0438 \u000d\u000a\u041a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u043e \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0438 Vision 2030, \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0439 \u043d\u0430 \u000d\u000a\u0434\u0438\u0432\u0435\u0440\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044e \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0438 \u0438 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u043e-\u0441\u044b\u0440\u044c\u0435\u0432\u043e\u0433\u043e \u0441\u0435\u043a\u0442\u043e\u0440\u0430.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u0438\u043d\u0432\u0435\u0441\u0442\u043e\u0440\u0430\u043c \u000d\u000a\u043d\u043e\u0432\u044b\u0435 \u0443\u0447\u0430\u0441\u0442\u043a\u0438 \u0434\u043b\u044f \u0433\u0435\u043e\u043b\u043e\u0433\u043e\u0440\u0430\u0437\u0432\u0435\u0434\u043e\u0447\u043d\u044b\u0445 \u0440\u0430\u0431\u043e\u0442 \u043d\u0430 \u000d\u000a\u043f\u043b\u043e\u0449\u0430\u0434\u0438 \u043f\u043e\u0447\u0442\u0438 17 \u0442\u044b\u0441. \u043a\u043c2, \u0437\u0430\u043c\u0435\u0441\u0442\u0438\u0442\u0435\u043b\u044c \u000d\u000a\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430 \u0422\u0443\u0440\u043a\u0438 \u0430\u043b\u044c-\u0411\u0430\u0431\u0442\u0435\u0439\u043d. \u000d\u000a\u041d\u0430 \u0442\u0435\u043d\u0434\u0435\u0440 \u0443\u0436\u0435 \u0432\u044b\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u044b \u0443\u0447\u0430\u0441\u0442\u043a\u0438 \u043f\u043b\u043e\u0449\u0430\u0434\u044c\u044e \u000d\u000a\u043e\u043a\u043e\u043b\u043e 33 \u0442\u044b\u0441. \u043a\u043c2, \u0430 \u0434\u043e \u043a\u043e\u043d\u0446\u0430 \u0433\u043e\u0434\u0430 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c \u000d\u000a\u0432\u044b\u0440\u0430\u0441\u0442\u0435\u0442 \u0434\u043e 50 \u0442\u044b\u0441. \u043a\u043c2.\u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u000d\u000a\u0418\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u044f \u0441\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0435\u043d\u044b \u0432 \u0440\u0430\u0439\u043e\u043d\u0435 \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u0449\u0438\u0442\u0430 \u043f\u043b\u043e\u0449\u0430\u0434\u044c\u044e \u043e\u043a\u043e\u043b\u043e 600 \u0442\u044b\u0441. \u000d\u000a\u043a\u043c2. \u041f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u043a\u0430\u043c\u043f\u0430\u043d\u0438\u0438 2023 \u0433\u043e\u0434\u0430 \u043e\u0446\u0435\u043d\u043a\u0430 \u000d\u000a\u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0441\u0442\u0440\u0430\u043d\u044b \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043f\u043e\u0447\u0442\u0438 \u000d\u000a\u0432\u0434\u0432\u043e\u0435 \u2014 \u0441 $1,3 \u0434\u043e $2,5 \u0442\u0440\u043b\u043d.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0430\u043d\u0430\u0434\u0441\u043a\u0430\u044f Aya \u043e\u0446\u0435\u043d\u0438\u043b\u0430 \u043f\u0440\u043e\u0435\u043a\u0442 Boumadine \u0432 \u041c\u0430\u0440\u043e\u043a\u043a\u043e \u000d\u000a\u0432 $3 \u043c\u043b\u0440\u0434 \u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442 \u043d\u0430 \u0431\u044b\u0441\u0442\u0440\u0443\u044e \u043e\u043a\u0443\u043f\u0430\u0435\u043c\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u0432\u044b\u0441\u043e\u043a\u0438\u043c \u0446\u0435\u043d\u0430\u043c \u000d\u000a\u043d\u0430 \u0437\u043e\u043b\u043e\u0442\u043e \u0438 \u0441\u0435\u0440\u0435\u0431\u0440\u043e.\u000d\u000a\u041a\u0430\u043d\u0430\u0434\u0441\u043a\u0430\u044f Aya Gold & Silver \u000d\u000a\u043e \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u043f\u043e\u043b\u0438\u043c\u0435\u0442\u0430\u043b\u043b\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u000d\u000aBoumadine \u0432 \u043f\u0440\u043e\u0432\u0438\u043d\u0446\u0438\u0438 \u042d\u0440-\u0420\u0430\u0448\u0438\u0434\u0438\u044f \u043d\u0430 \u0432\u043e\u0441\u0442\u043e\u043a\u0435 \u000d\u000a\u041c\u0430\u0440\u043e\u043a\u043a\u043e \u2014 $3 \u043c\u043b\u0440\u0434. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0432\u043b\u0430\u0434\u0435\u0435\u0442 85% \u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u0438 \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0448\u0435\u0441\u0442\u0438 \u000d\u000a\u043a\u0430\u0440\u044c\u0435\u0440\u043e\u0432 \u0438 \u0442\u0440\u0435\u0445 \u0448\u0430\u0445\u0442 \u0441\u043e \u0441\u0440\u043e\u043a\u043e\u043c \u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u0438 \u000d\u000a11 \u043b\u0435\u0442 \u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u043a\u0438 8 \u0442\u044b\u0441. \u0442\u043e\u043d\u043d \u2028\u000d\u000a\u0440\u0443\u0434\u044b \u0432 \u0441\u0443\u0442\u043a\u0438.\u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430 \u041f\u0440\u0438 \u0446\u0435\u043d\u0435 \u0437\u043e\u043b\u043e\u0442\u0430 $4 \u0442\u044b\u0441. \u0437\u0430 \u0443\u043d\u0446\u0438\u044e \u0447\u0438\u0441\u0442\u0430\u044f \u000d\u000a\u043f\u0440\u0438\u0432\u0435\u0434\u0435\u043d\u043d\u0430\u044f \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442 \u000d\u000a$3 \u043c\u043b\u0440\u0434, \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u044f\u044f \u043d\u043e\u0440\u043c\u0430 \u0434\u043e\u0445\u043e\u0434\u043d\u043e\u0441\u0442\u0438 77%, \u000d\u000a\u0441\u0440\u043e\u043a \u043e\u043a\u0443\u043f\u0430\u0435\u043c\u043e\u0441\u0442\u0438 1,2 \u0433\u043e\u0434\u0430. \u0421\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u000d\u000a\u0437\u0430\u0439\u043c\u0435\u0442 \u0434\u0432\u0430 \u0433\u043e\u0434\u0430, \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u0442\u0440\u0430\u0442\u044b \u000d\u000a\u043e\u0446\u0435\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0432 $446 \u043c\u043b\u043d, \u0435\u0436\u0435\u0433\u043e\u0434\u043d\u044b\u0435 \u000d\u000a\u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u0440\u0430\u0441\u0445\u043e\u0434\u044b $30 \u043c\u043b\u043d.\u000d\u000a02 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 7\u201314 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041f\u0440\u0438\u0431\u044b\u043b\u044c \u0441\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 Maaden \u0432\u043e II \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 \u2028\u000d\u000a\u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 127% \u000d\u000a\u0420\u043e\u0441\u0442 \u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0439 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u0441\u0432\u044f\u0437\u0430\u043d \u000d\u000a\u0441 \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435\u043c \u043f\u0440\u043e\u0434\u0430\u0436 \u0438 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435\u043c \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0445 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432.\u000d\u000aMaaden \u043e\u0442\u0447\u0435\u0442 \u043e \u0440\u043e\u0441\u0442\u0435 \u0447\u0438\u0441\u0442\u043e\u0439 \u000d\u000a\u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u0434\u043e $587 \u043c\u043b\u043d, \u0447\u0442\u043e \u043d\u0430 127% \u0432\u044b\u0448\u0435 \u000d\u000a\u0443\u0440\u043e\u0432\u043d\u044f \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e \u0433\u043e\u0434\u0430. \u0412\u044b\u0440\u0443\u0447\u043a\u0430 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430\u0441\u044c \u000d\u000a\u043d\u0430 24% \u2014 \u0434\u043e $2,67 \u043c\u043b\u0440\u0434 \u2014 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u0440\u043e\u0441\u0442\u0443 \u000d\u000a\u0446\u0435\u043d \u043d\u0430 \u0441\u044b\u0440\u044c\u0435 \u0438 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044e \u043f\u0440\u043e\u0434\u0430\u0436 \u000d\u000a\u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432, \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u0438 \u0437\u043e\u043b\u043e\u0442\u0430.\u000d\u000a\u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043b\u0430 \u0417\u0430 \u0434\u0435\u0432\u044f\u0442\u044c \u043c\u0435\u0441\u044f\u0446\u0435\u0432 2025 \u0433\u043e\u0434\u0430 \u0432\u044b\u0440\u0443\u0447\u043a\u0430 \u000d\u000a\u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 $7,5 \u043c\u043b\u0440\u0434, \u0430 \u0447\u0438\u0441\u0442\u0430\u044f \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u000d\u000a\u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 91% \u2014 \u0434\u043e $1,5 \u043c\u043b\u0440\u0434. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u0441\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u0430 \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u0442\u0440\u0430\u0442 \u000d\u000a\u0432 \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d\u0435 $7,55\u20139,55 \u043c\u043b\u0440\u0434. \u0410\u043a\u0446\u0438\u0438 Maaden \u000d\u000a\u0441 \u043d\u0430\u0447\u0430\u043b\u0430 \u0433\u043e\u0434\u0430 \u043f\u043e\u0434\u043e\u0440\u043e\u0436\u0430\u043b\u0438 \u043d\u0430 50%.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u0430\u0432\u0438\u0430\u0446\u0438\u044f\u000d\u000aDHL \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 $85 \u043c\u043b\u043d \u0432 \u0430\u0432\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0442\u0435\u0445\u0446\u0435\u043d\u0442\u0440 \u000d\u000a\u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435\u000d\u000a\u0418\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0432 \u043f\u0440\u043e\u0435\u043a\u0442 \u0441\u0442\u0430\u043d\u0443\u0442 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u0432\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u043c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0432 \u0430\u0432\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u0443\u044e \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u0440\u0435\u0433\u0438\u043e\u043d\u0430.\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f DHL \u043e \u043f\u043b\u0430\u043d\u0430\u0445 \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u000d\u000a\u043f\u0435\u0440\u0432\u044b\u0439 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0435 \u0446\u0435\u043d\u0442\u0440 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u043d\u0438\u044f \u0441\u0430\u043c\u043e\u043b\u0435\u0442\u043e\u0432 \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u000d\u000a\u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u0430\u044d\u0440\u043e\u043f\u043e\u0440\u0442\u0430 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0430. \u041e\u0431\u044a\u0435\u043c \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442 32 \u043c\u043b\u043d \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0438\u0445 \u000d\u000a\u0434\u0438\u043d\u0430\u0440\u043e\u0432 ($85 \u043c\u043b\u043d). \u000a\u000d\u000a\u041f\u043b\u043e\u0449\u0430\u0434\u044c \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u0430 \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u0442 33,8 \u0442\u044b\u0441. \u043c2, \u000d\u000a\u043e\u0434\u0438\u043d \u0442\u043e\u043b\u044c\u043a\u043e \u0430\u043d\u0433\u0430\u0440 \u0437\u0430\u0439\u043c\u0435\u0442 9,8 \u0442\u044b\u0441. \u043c2. \u0426\u0435\u043d\u0442\u0440 \u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b\u0430 \u0431\u0443\u0434\u0435\u0442 \u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u0442\u044c Boeing 777 \u0438 767. \u041d\u0430\u0447\u0430\u043b\u043e \u000d\u000a\u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u0442\u0441\u044f \u0432 \u043e\u043a\u0442\u044f\u0431\u0440\u0435 2026 \u000d\u000a\u0433\u043e\u0434\u0430, \u0432\u0432\u043e\u0434 \u0432 \u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u044e \u2014 \u0432 \u0430\u0432\u0433\u0443\u0441\u0442\u0435 2028-\u0433\u043e.\u000a\u000d\u000a\u0420\u0430\u043d\u0435\u0435 DHL \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u043e \u043f\u043b\u0430\u043d\u0430\u0445 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u000d\u000a\u0431\u043e\u043b\u0435\u0435 \u20ac500 \u043c\u043b\u043d \u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u0431\u0438\u0437\u043d\u0435\u0441\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u000d\u000a\u0412\u043e\u0441\u0442\u043e\u043a\u0435. \u0412 \u043f\u0435\u0440\u0432\u0443\u044e \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0430 \u000d\u000a\u0440\u0430\u0441\u0448\u0438\u0440\u0438\u0442\u044c \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0438 \u0432 \u041e\u0410\u042d \u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u0438.\u000d\u000a03 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 7\u201314 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c\u000d\u000a\u041f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u000d\u000a\u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u0432\u044b\u0440\u043e\u0441\u043b\u043e \u043d\u0430 9,3% \u000d\u000a\u0420\u043e\u0441\u0442 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435\u043c \u0434\u043e\u0431\u044b\u0447\u0438 \u043d\u0435\u0444\u0442\u0438 \u0438 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u0432 \u0433\u0430\u0437\u043e\u0432\u0443\u044e \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443.\u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0430\u044f \u0410\u0440\u0430\u0432\u0438\u044f \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043b\u0430 \u0440\u043e\u0441\u0442 \u000d\u000a\u0438\u043d\u0434\u0435\u043a\u0441\u0430 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 2025 \u0433\u043e\u0434\u0430 \u043d\u0430 9,3% \u0432 \u0433\u043e\u0434\u043e\u0432\u043e\u043c \u000d\u000a\u0432\u044b\u0440\u0430\u0436\u0435\u043d\u0438\u0438, \u0434\u0430\u043d\u043d\u044b\u0435 \u0413\u043b\u0430\u0432\u043d\u043e\u0433\u043e \u000d\u000a\u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438 \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430.\u000a\u000d\u000a\u0414\u043e\u0431\u044b\u0447\u0430 \u043d\u0435\u0444\u0442\u0438 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0430 9,97 \u043c\u043b\u043d \u0431\u0430\u0440\u0440\u0435\u043b\u0435\u0439 \u000d\u000a\u0432 \u0441\u0443\u0442\u043a\u0438 \u043f\u0440\u043e\u0442\u0438\u0432 8,97 \u043c\u043b\u043d \u0433\u043e\u0434\u043e\u043c \u0440\u0430\u043d\u0435\u0435. \u000d\u000a\u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443\u044e\u0442\u000d\u000a\u041f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0441\u0435\u043a\u0442\u043e\u0440 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0441\u044f \u000d\u000a\u043d\u0430 6,3%, \u0430 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u2014 \u043d\u0430 12,6% \u000d\u000a\u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0443 \u043d\u0430 \u043f\u0440\u0438\u0440\u043e\u0434\u043d\u044b\u0439 \u0433\u0430\u0437. \u000d\u000a\u0418\u043d\u0434\u0435\u043a\u0441 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b 116,1 \u043f\u0443\u043d\u043a\u0442\u0430 \u043f\u0440\u043e\u0442\u0438\u0432 106,3 \u0433\u043e\u0434\u043e\u043c \u000d\u000a\u0440\u0430\u043d\u0435\u0435.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u042d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u0430\u044f DP World \u043f\u0440\u0438\u0441\u0442\u0443\u043f\u0438\u043b\u0430 \u043a \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044e \u000d\u000a\u0441\u0438\u0440\u0438\u0439\u0441\u043a\u0438\u043c \u043f\u043e\u0440\u0442\u043e\u043c \u0422\u0430\u0440\u0442\u0443\u0441\u000d\u000aDP World \u0432\u0437\u044f\u043b\u0430 \u043f\u043e\u0434 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043e\u0434\u0438\u043d \u0438\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u043f\u043e\u0440\u0442\u043e\u0432 \u0412\u043e\u0441\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u0421\u0440\u0435\u0434\u0438\u0437\u0435\u043c\u043d\u043e\u043c\u043e\u0440\u044c\u044f, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0441\u0442\u0430\u043d\u0435\u0442 \u043e\u043f\u043e\u0440\u043d\u044b\u043c \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u0445\u0430\u0431\u043e\u043c \u0440\u0435\u0433\u0438\u043e\u043d\u0430. \u000d\u000a\u041b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440 \u0438\u0437 \u0414\u0443\u0431\u0430\u044f \u000d\u000a\u043e \u043d\u0430\u0447\u0430\u043b\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0441\u0438\u0440\u0438\u0439\u0441\u043a\u0438\u043c \u043f\u043e\u0440\u0442\u043e\u043c \u0422\u0430\u0440\u0442\u0443\u0441. \u000d\u000a\u0414\u043e 2024 \u0433\u043e\u0434\u0430 \u043f\u043e\u0440\u0442\u043e\u043c \u0432\u043b\u0430\u0434\u0435\u043b\u0430 \u0440\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u0430\u044f \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u00ab\u0421\u0422\u0413 \u0418\u043d\u0436\u0438\u043d\u0438\u0440\u0438\u043d\u0433\u00bb, \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u0432\u0448\u0430\u044f \u000d\u000a\u0432 2019 \u0433\u043e\u0434\u0443 \u043a\u043e\u043d\u0442\u0440\u0430\u043a\u0442 \u043d\u0430 49 \u043b\u0435\u0442 \u0441 \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u044f\u043c\u0438 \u000d\u000a\u0441\u0432\u044b\u0448\u0435 $500 \u043c\u043b\u043d. \u000a\u000d\u000a\u0412 \u043c\u0430\u0435 \u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441\u0443\u0445\u0438\u0445 \u0438 \u043c\u043e\u0440\u0441\u043a\u0438\u0445 \u000d\u000a\u043f\u043e\u0440\u0442\u043e\u0432 \u0421\u0438\u0440\u0438\u0438 \u0438 DP World \u0437\u0430\u043a\u043b\u044e\u0447\u0438\u043b\u0438 \u000d\u000a\u043c\u0435\u043c\u043e\u0440\u0430\u043d\u0434\u0443\u043c \u043e \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0438 \u0438 \u044d\u043a\u0441\u043f\u043b\u0443\u0430\u0442\u0430\u0446\u0438\u0438 \u000d\u000a\u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u0430 \u0432 \u0422\u0430\u0440\u0442\u0443\u0441\u0435, \u0430 \u0432 \u0438\u044e\u043b\u0435 \u2014 \u000d\u000a\u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435, \u000d\u000a\u043f\u0440\u0435\u0434\u0443\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u044e\u0449\u0435\u0435 \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0445 \u000d\u000a\u043a\u043b\u0430\u0441\u0442\u0435\u0440\u043e\u0432 \u0438 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0445 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0437\u043e\u043d.\u000a\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u0440\u043e\u0432\u043e\u0434\u0438\u0442 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d\u0443\u044e \u043e\u0446\u0435\u043d\u043a\u0443 \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u043f\u043e\u0440\u0442\u0430, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u043f\u0440\u0438\u0447\u0430\u043b\u044b, \u000d\u000a\u0441\u043a\u043b\u0430\u0434\u044b \u0438 \u043e\u0431\u043e\u0440\u0443\u0434\u043e\u0432\u0430\u043d\u0438\u0435. \u041d\u0430 \u043f\u0435\u0440\u0432\u043e\u043c \u044d\u0442\u0430\u043f\u0435 \u000d\u000a\u0437\u0430\u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u0434\u043d\u043e\u0443\u0433\u043b\u0443\u0431\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0440\u0430\u0431\u043e\u0442\u044b \u000d\u000a\u0438 \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u044f \u0442\u0435\u0445\u043d\u0438\u043a\u0438, \u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u0441\u0440\u043e\u0447\u043d\u043e\u0439 \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b \u043f\u0435\u0440\u0441\u043f\u0435\u043a\u0442\u0438\u0432\u0435 \u2014 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 \u0441\u043a\u043b\u0430\u0434\u0441\u043a\u0438\u0445 \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0435\u0439 \u0438 \u0440\u0435\u043a\u043e\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f \u0442\u0435\u0440\u043c\u0438\u043d\u0430\u043b\u043e\u0432. \u000a\u000d\u000a\u041f\u043e \u043e\u0446\u0435\u043d\u043a\u0435 DP World, \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u000d\u000a\u043f\u043e\u0437\u0432\u043e\u043b\u0438\u0442 \u0422\u0430\u0440\u0442\u0443\u0441\u0443 \u0441\u0442\u0430\u0442\u044c \u0441\u0442\u0440\u0430\u0442\u0435\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u000d\u000a\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u0446\u0435\u043d\u0442\u0440\u043e\u043c \u0412\u043e\u0441\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u000d\u000a\u0421\u0440\u0435\u0434\u0438\u0437\u0435\u043c\u043d\u043e\u043c\u043e\u0440\u044c\u044f \u0438 \u0443\u0441\u043a\u043e\u0440\u0438\u0442 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u000d\u000a\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u0421\u0438\u0440\u0438\u0438.\u000d\u000a04 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 7\u201314 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b #\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u041f\u0435\u0440\u0432\u043e\u0435 \u0441 \u043d\u0430\u0447\u0430\u043b\u0430 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0432 \u0413\u0430\u0437\u0435 \u0441\u0432\u0435\u0440\u0445\u043a\u0440\u0443\u043f\u043d\u043e\u0435 \u000d\u000a\u0441\u0443\u0434\u043d\u043e \u043f\u0440\u043e\u0448\u043b\u043e \u0447\u0435\u0440\u0435\u0437 \u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u043a\u0430\u043d\u0430\u043b\u000d\u000a\u041f\u0440\u043e\u0445\u043e\u0434 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043e\u0432\u043e\u0437\u0430 \u0441\u0442\u0430\u043b \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u043e\u043c \u0441\u0442\u0430\u0431\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u043e\u0431\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u043c \u043c\u043e\u0440\u0435 \u000d\u000a\u0438 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0433\u043e \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f \u0442\u0440\u0430\u043d\u0437\u0438\u0442\u0430 \u043c\u0435\u0436\u0434\u0443 \u0415\u0432\u0440\u043e\u043f\u043e\u0439 \u0438 \u0410\u0437\u0438\u0435\u0439.\u000d\u000a\u0424\u0440\u0430\u043d\u0446\u0443\u0437\u0441\u043a\u0438\u0439 \u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043e\u0432\u043e\u0437 Benjamin Franklin \u000d\u000a\u0434\u043b\u0438\u043d\u043e\u0439 399 \u043c \u0438 \u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e\u0441\u0442\u044c\u044e 17,8 \u0442\u044b\u0441. TEU \u000d\u000a\u043f\u0440\u043e\u0448\u0435\u043b \u0447\u0435\u0440\u0435\u0437 \u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u043a\u0430\u043d\u0430\u043b \u0432 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0438 \u000d\u000a\u041c\u0430\u043b\u0430\u0439\u0437\u0438\u0438 \u2014 \u043f\u0435\u0440\u0432\u043e\u0435 \u0441\u0432\u0435\u0440\u0445\u043a\u0440\u0443\u043f\u043d\u043e\u0435 \u0441\u0443\u0434\u043d\u043e, \u000d\u000a\u043f\u0435\u0440\u0435\u0441\u0435\u043a\u0448\u0435\u0435 \u043a\u0430\u043d\u0430\u043b \u0437\u0430 \u0434\u0432\u0430 \u0433\u043e\u0434\u0430. \u041f\u043e \u000d\u000a\u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u043a\u0430\u043d\u0430\u043b\u0430, \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0432\u043d\u043e\u0432\u044c \u043e\u0442\u043a\u0440\u044b\u0442 \u000d\u000a\u0434\u043b\u044f \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u043d\u044b\u0445 \u0440\u0435\u0439\u0441\u043e\u0432.\u000a\u000d\u000a\u0413\u043b\u0430\u0432\u0430 \u0432\u0435\u0434\u043e\u043c\u0441\u0442\u0432\u0430 \u041e\u0441\u0430\u043c\u0430 \u0420\u0430\u0431\u0438\u0430 \u0437\u0430\u044f\u0432\u0438\u043b, \u0447\u0442\u043e \u000d\u000a\u0437\u0430 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u043c\u0435\u0441\u044f\u0446\u044b \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e \u000d\u000a\u0434\u0430\u043d\u043d\u044b\u043c\u000d\u000a28 \u0442\u0440\u0430\u043d\u0437\u0438\u0442\u043e\u0432 \u0441\u0440\u0435\u0434\u043d\u0435\u0442\u043e\u043d\u043d\u0430\u0436\u043d\u044b\u0445 \u000d\u000a\u043a\u043e\u043d\u0442\u0435\u0439\u043d\u0435\u0440\u043e\u0432\u043e\u0437\u043e\u0432 \u0438 2 \u0440\u0435\u0439\u0441\u0430 \u043a\u0440\u0443\u043f\u043d\u044b\u0445 \u0441\u0443\u0434\u043e\u0432, \u000d\u000a\u0432 \u0442\u043e\u043c \u0447\u0438\u0441\u043b\u0435 19 \u0444\u0440\u0430\u043d\u0446\u0443\u0437\u0441\u043a\u043e\u0439 CMA CGM \u2028\u000d\u000a\u0438 9 \u0448\u0432\u0435\u0439\u0446\u0430\u0440\u0441\u043a\u043e\u0439 MSC. \u000a\u000d\u000a\u0415\u0433\u0438\u043f\u0435\u0442 \u043f\u043e\u0442\u0435\u0440\u044f\u043b \u0431\u043e\u043b\u0435\u0435 $9 \u043c\u043b\u0440\u0434 \u0434\u043e\u0445\u043e\u0434\u043e\u0432 \u0438\u0437-\u0437\u0430 \u000d\u000a\u043a\u0440\u0438\u0437\u0438\u0441\u0430 \u0432 \u041a\u0440\u0430\u0441\u043d\u043e\u043c \u043c\u043e\u0440\u0435, \u0432\u044b\u0437\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u043d\u0430\u043f\u0430\u0434\u0435\u043d\u0438\u044f\u043c\u0438 \u0445\u0443\u0441\u0438\u0442\u043e\u0432. \u0414\u043e \u044d\u0441\u043a\u0430\u043b\u0430\u0446\u0438\u0438 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u000d\u000a\u0421\u0443\u044d\u0446\u043a\u0438\u0439 \u043a\u0430\u043d\u0430\u043b \u043f\u0440\u0438\u043d\u043e\u0441\u0438\u043b \u043e\u043a\u043e\u043b\u043e $10 \u043c\u043b\u0440\u0434 \u0432 \u0433\u043e\u0434.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000aEmsteel \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430 \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u043d\u0430 209% \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u000d\u000a\u0440\u043e\u0441\u0442\u0443 \u043f\u0440\u043e\u0434\u0430\u0436 \u0441\u0442\u0430\u043b\u0438 \u0438 \u0446\u0435\u043c\u0435\u043d\u0442\u0430 \u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 16 \u0437\u0430\u0432\u043e\u0434\u0430\u043c\u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e 3,5 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0441\u0442\u0430\u043b\u0438 \u0438 4,6 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0446\u0435\u043c\u0435\u043d\u0442\u0430. \u000d\u000a\u0427\u0438\u0441\u0442\u0430\u044f \u043f\u0440\u0438\u0431\u044b\u043b\u044c \u044d\u043c\u0438\u0440\u0430\u0442\u0441\u043a\u043e\u0439 Emsteel \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u2028\u000d\u000a\u043d\u0430 209% \u2014 \u0434\u043e 283 \u043c\u043b\u043d \u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 ($77 \u043c\u043b\u043d) \u2014 \u000d\u000a\u0437\u0430 \u0434\u0435\u0432\u044f\u0442\u044c \u043c\u0435\u0441\u044f\u0446\u0435\u0432 2025 \u0433\u043e\u0434\u0430 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u044e \u043f\u0440\u043e\u0434\u0430\u0436 \u0441\u0442\u0430\u043b\u0438, \u0446\u0435\u043c\u0435\u043d\u0442\u0430 \u0438 \u043a\u043b\u0438\u043d\u043a\u0435\u0440\u0430. \u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e \u0440\u043e\u0441\u0442\u0435 \u0432\u044b\u0440\u0443\u0447\u043a\u0438 \u043d\u0430 10%, \u000d\u000a\u0434\u043e 6,5 \u043c\u043b\u0440\u0434 \u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 ($1,77 \u043c\u043b\u0440\u0434). \u000a\u000d\u000a\u041f\u0440\u043e\u0434\u0430\u0436\u0438 \u0441\u0442\u0430\u043b\u0438 \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 9%, \u0446\u0435\u043c\u0435\u043d\u0442\u0430 \u000d\u000a\u0438 \u043a\u043b\u0438\u043d\u043a\u0435\u0440\u0430 \u2014 \u043d\u0430 17%. \u0421\u0435\u0433\u043c\u0435\u043d\u0442 \u0441\u0442\u0430\u043b\u0438 \u043f\u0440\u0438\u043d\u0435\u0441 \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430\u000d\u000a5,8 \u043c\u043b\u0440\u0434 \u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 \u0434\u043e\u0445\u043e\u0434\u043e\u0432, \u0430 \u0446\u0435\u043c\u0435\u043d\u0442\u0430 \u2014 \u000d\u000a652 \u043c\u043b\u043d. \u0412 III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 \u043e\u0431\u0449\u0430\u044f \u0432\u044b\u0440\u0443\u0447\u043a\u0430 \u000d\u000a\u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0430\u0441\u044c \u043d\u0430 13% \u0433\u043e\u0434 \u043a \u0433\u043e\u0434\u0443.\u000a\u000d\u000a\u0421\u0443\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u0444\u043e\u043d\u0434 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u0432\u043b\u0430\u0434\u0435\u0435\u0442 87,5% \u000d\u000a\u0430\u043a\u0446\u0438\u0439 Emsteel, \u043e\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044f 12,5% \u043d\u0430\u0445\u043e\u0434\u044f\u0442\u0441\u044f \u000d\u000a\u0432 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e\u043c \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0438.\u000d\u000a05 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a \u0438 \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 7\u201314 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0422\u0440\u0430\u043c\u043f \u043f\u0440\u0438\u043d\u044f\u043b \u0432 \u0411\u0435\u043b\u043e\u043c \u0434\u043e\u043c\u0435 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u000d\u000a\u0421\u0438\u0440\u0438\u0438\u000d\u000a\u042d\u0442\u043e \u043f\u0435\u0440\u0432\u044b\u0439 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u0438\u0437\u0438\u0442 \u0441\u0438\u0440\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u043b\u0438\u0434\u0435\u0440\u0430 \u0432 \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d \u0437\u0430 \u0447\u0435\u0442\u0432\u0435\u0440\u0442\u044c \u0432\u0435\u043a\u0430.\u000d\u000a\u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0421\u0428\u0410 \u0414\u043e\u043d\u0430\u043b\u044c\u0434 \u0422\u0440\u0430\u043c\u043f \u043f\u0440\u0438\u043d\u044f\u043b \u0432 \u0411\u0435\u043b\u043e\u043c \u000d\u000a\u0434\u043e\u043c\u0435 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0433\u043e \u0433\u043b\u0430\u0432\u0443 \u0421\u0438\u0440\u0438\u0438 \u0410\u0445\u043c\u0435\u0434\u0430 \u2028\u000d\u000a\u0430\u0448-\u0428\u0430\u0440\u0430\u0430. \u041b\u0438\u0434\u0435\u0440\u044b \u043d\u0435 \u0434\u0435\u043b\u0430\u043b\u0438 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u044b\u0445 \u000d\u000a\u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0439 \u0438 \u0438\u0437\u0431\u0435\u0436\u0430\u043b\u0438 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0445 \u0432\u044b\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0439.\u000a\u000d\u000a\u0410\u0448-\u0428\u0430\u0440\u0430\u0430, \u0440\u0430\u043d\u0435\u0435 \u0432\u043e\u0437\u0433\u043b\u0430\u0432\u043b\u044f\u0432\u0448\u0438\u0439 \u0433\u0440\u0443\u043f\u043f\u0438\u0440\u043e\u0432\u043a\u0443 \u000d\u000a\u00ab\u0425\u0430\u0439\u0430\u0442 \u0422\u0430\u0445\u0440\u0438\u0440 \u0430\u0448-\u0428\u0430\u043c\u00bb, \u043f\u0440\u0438\u0448\u0435\u043b \u043a \u0432\u043b\u0430\u0441\u0442\u0438 \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u0441\u0432\u0435\u0440\u0436\u0435\u043d\u0438\u044f \u0411\u0430\u0448\u0430\u0440\u0430 \u0410\u0441\u0430\u0434\u0430, \u043f\u043e\u043b\u0443\u0447\u0438\u0432\u0448\u0435\u0433\u043e \u000d\u000a\u0443\u0431\u0435\u0436\u0438\u0449\u0435 \u0432 \u0420\u043e\u0441\u0441\u0438\u0438. \u041f\u0440\u0438 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0435 \u043f\u0440\u0438\u043d\u0446\u0430 \u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u0438 \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u0422\u0443\u0440\u0446\u0438\u0438 \u043e\u043d \u000d\u000a\u0434\u043e\u0431\u0438\u043b\u0441\u044f \u0441\u043d\u044f\u0442\u0438\u044f \u0447\u0430\u0441\u0442\u0438 \u0441\u0430\u043d\u043a\u0446\u0438\u0439 \u0438 \u043f\u044b\u0442\u0430\u0435\u0442\u0441\u044f \u000d\u000a\u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0435 \u0441\u0432\u044f\u0437\u0438 \u0414\u0430\u043c\u0430\u0441\u043a\u0430.\u000d\u000a\u041f\u0440\u0438\u0431\u044b\u0442\u0438\u0435 \u0430\u0448-\u0428\u0430\u0440\u0430\u0430 \u0432 \u0411\u0435\u043b\u044b\u0439 \u0434\u043e\u043c \u0432\u044b\u0433\u043b\u044f\u0434\u0435\u043b\u043e \u000d\u000a\u0441\u043a\u0440\u043e\u043c\u043d\u0435\u0435, \u0447\u0435\u043c \u043e\u0431\u044b\u0447\u043d\u043e \u043e\u0431\u0441\u0442\u0430\u0432\u043b\u044f\u044e\u0442 \u0432\u0438\u0437\u0438\u0442\u044b \u000d\u000a\u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445 \u043b\u0438\u0434\u0435\u0440\u043e\u0432. \u041e\u043d \u0432\u043e\u0448\u0435\u043b \u0432 \u0411\u0435\u043b\u044b\u0439 \u0434\u043e\u043c \u000d\u000a\u0447\u0435\u0440\u0435\u0437 \u0431\u043e\u043a\u043e\u0432\u043e\u0439 \u0432\u0445\u043e\u0434, \u0430 \u043d\u0435 \u0447\u0435\u0440\u0435\u0437 \u0433\u043b\u0430\u0432\u043d\u043e\u0435 \u000d\u000a\u043a\u0440\u044b\u043b\u044c\u0446\u043e \u0417\u0430\u043f\u0430\u0434\u043d\u043e\u0433\u043e \u043a\u0440\u044b\u043b\u0430, \u0433\u0434\u0435 \u0438\u043d\u043e\u0441\u0442\u0440\u0430\u043d\u043d\u044b\u0445 \u000d\u000a\u0433\u043e\u0441\u0442\u0435\u0439 \u0447\u0430\u0441\u0442\u043e \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u0442 \u0441\u0430\u043c \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442. \u041f\u043e\u0441\u043b\u0435 \u000d\u000a\u0432\u0438\u0437\u0438\u0442\u0430 \u0433\u043b\u0430\u0432\u0430 \u0421\u0438\u0440\u0438\u0438 \u0432\u044b\u0448\u0435\u043b \u0438\u0437 \u0411\u0435\u043b\u043e\u0433\u043e \u0434\u043e\u043c\u0430 \u000d\u000a\u0447\u0435\u0440\u0435\u0437 \u0442\u0443 \u0436\u0435 \u0434\u0432\u0435\u0440\u044c.\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000a\u0411\u044e\u0434\u0436\u0435\u0442\u043d\u044b\u0439 \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u0432\u044b\u0440\u043e\u0441 \u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u044f \u0434\u043e\u0445\u043e\u0434\u043e\u0432 \u000d\u000a\u0421\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u043d\u0435\u0444\u0442\u044f\u043d\u044b\u0445 \u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0439 \u0438 \u0440\u043e\u0441\u0442 \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 \u0443\u0441\u0438\u043b\u0438\u043b\u0438 \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u0433\u043e\u0441\u0444\u0438\u043d\u0430\u043d\u0441\u044b \u000d\u000a\u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0441\u0442\u0432\u0430.\u000d\u000a\u0411\u044e\u0434\u0436\u0435\u0442\u043d\u044b\u0439 \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u000d\u000a\u0432 III \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0435 2025 \u0433\u043e\u0434\u0430, \u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432, \u0434\u043e\u0441\u0442\u0438\u0433 88,5 \u043c\u043b\u0440\u0434 \u000d\u000a\u0440\u0438\u0430\u043b\u043e\u0432 ($23,6 \u043c\u043b\u0440\u0434), \u0447\u0442\u043e \u043d\u0430 157% \u0432\u044b\u0448\u0435 \u000d\u000a\u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0435\u0433\u043e \u043a\u0432\u0430\u0440\u0442\u0430\u043b\u0430.\u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e\u000d\u000a\u041d\u0435\u0444\u0442\u044f\u043d\u044b\u0435 \u0434\u043e\u0445\u043e\u0434\u044b \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0438 151 \u043c\u043b\u0440\u0434 \u0440\u0438\u0430\u043b\u043e\u0432, \u000d\u000a\u0430 \u043e\u0431\u0449\u0438\u0435 269,9 \u043c\u043b\u0440\u0434, \u0441\u043d\u0438\u0437\u0438\u0432\u0448\u0438\u0441\u044c \u043d\u0430 13% \u000d\u000a\u0432 \u0433\u043e\u0434\u043e\u0432\u043e\u043c \u0432\u044b\u0440\u0430\u0436\u0435\u043d\u0438\u0438. \u0420\u0430\u0441\u0445\u043e\u0434\u044b \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 6%, \u000d\u000a\u0434\u043e 358,4 \u043c\u043b\u0440\u0434 \u0440\u0438\u0430\u043b\u043e\u0432. \u041f\u0440\u043e\u0433\u043d\u043e\u0437 \u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430 \u2028\u000d\u000a\u043d\u0430 2025 \u0433\u043e\u0434 \u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440\u0435\u043d \u0434\u043e 245 \u043c\u043b\u0440\u0434 \u0440\u0438\u0430\u043b\u043e\u0432 \u000d\u000a($65,3 \u043c\u043b\u0440\u0434).\u000d\u000a06 09","\u041a\u0438\u0442\u0430\u0439 7\u201314 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u043e\u043d\u0433\u043e \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430 \u0440\u0430\u0431\u043e\u0442\u0443 \u0440\u0443\u0434\u043d\u0438\u043a\u0430 Huayou Cobalt \u000d\u000a\u0438\u0437-\u0437\u0430 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0439\u000d\u000a\u0412\u043b\u0430\u0441\u0442\u0438 \u0441\u0442\u0440\u0430\u043d\u044b \u0443\u0441\u0438\u043b\u0438\u0432\u0430\u044e\u0442 \u044d\u043a\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0432 \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0435\u043c \u0441\u0435\u043a\u0442\u043e\u0440\u0435.\u000d\u000a\u0412\u043b\u0430\u0441\u0442\u0438 \u0414\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438 \u041a\u043e\u043d\u0433\u043e \u000d\u000a \u043e \u0442\u0440\u0435\u0445\u043c\u0435\u0441\u044f\u0447\u043d\u043e\u0439 \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0435 \u0434\u043e\u0431\u044b\u0447\u0438 \u000d\u000a\u043d\u0430 \u043c\u0435\u0434\u043d\u043e-\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u043e\u0432\u043e\u043c \u0440\u0443\u0434\u043d\u0438\u043a\u0435 \u041b\u0443\u0438\u0441\u0432\u0438\u0448\u0438, \u000d\u000a\u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0449\u0435\u043c \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 Zhejiang Huayou \u000d\u000aCobalt, \u0438\u0437-\u0437\u0430 \u043f\u0440\u043e\u0440\u044b\u0432\u0430 \u0434\u0430\u043c\u0431\u044b \u0438 \u0437\u0430\u0433\u0440\u044f\u0437\u043d\u0435\u043d\u0438\u044f \u000d\u000a\u0432\u043e\u0434\u043e\u0435\u043c\u043e\u0432. \u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043e\u0431\u044f\u0437\u0430\u043d\u0430 \u0443\u0441\u0442\u0440\u0430\u043d\u0438\u0442\u044c \u000d\u000a\u043f\u043e\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u044f \u0430\u0432\u0430\u0440\u0438\u0438 \u0438 \u0432\u044b\u043f\u043b\u0430\u0442\u0438\u0442\u044c \u043a\u043e\u043c\u043f\u0435\u043d\u0441\u0430\u0446\u0438\u0438 \u000d\u000a\u0440\u0430\u0431\u043e\u0442\u043d\u0438\u043a\u0430\u043c \u0438 \u0436\u0438\u0442\u0435\u043b\u044f\u043c \u0431\u043b\u0438\u0437\u043b\u0435\u0436\u0430\u0449\u0438\u0445 \u0440\u0430\u0439\u043e\u043d\u043e\u0432.\u000a\u000d\u000a\u0412 \u0444\u0435\u0432\u0440\u0430\u043b\u0435 \u0432\u043b\u0430\u0441\u0442\u0438 \u0414\u0435\u043c\u043e\u043a\u0440\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438 \u000d\u000a\u041a\u043e\u043d\u0433\u043e, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0431\u043e\u043b\u0435\u0435 70% \u000d\u000a\u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430, \u0437\u0430\u043f\u0440\u0435\u0442\u0438\u043b\u0438 \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u044d\u0442\u043e\u0433\u043e \u043c\u0435\u0442\u0430\u043b\u043b\u0430, \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u0432\u044b\u0441\u0438\u0442\u044c \u0446\u0435\u043d\u044b \u000d\u000a\u043d\u0430 \u043d\u0435\u0433\u043e \u043d\u0430 \u043c\u0438\u0440\u043e\u0432\u043e\u043c \u0440\u044b\u043d\u043a\u0435. \u0412 \u043e\u043a\u0442\u044f\u0431\u0440\u0435 \u044d\u0442\u043e\u0442 \u000d\u000a\u0437\u0430\u043f\u0440\u0435\u0442 \u0431\u044b\u043b \u043e\u0442\u043c\u0435\u043d\u0435\u043d, \u043e\u0434\u043d\u0430\u043a\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u000d\u000a\u043a\u043e\u0431\u0430\u043b\u044c\u0442\u0430 \u0442\u0430\u043a \u0438 \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0438 \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0438\u000d\u000a\u043e\u0442 \u0432\u043b\u0430\u0441\u0442\u0435\u0439 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f\u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u0432\u0432\u0435\u0434\u0435\u043d\u043d\u043e\u0439 \u0440\u0430\u043d\u0435\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u044b \u043a\u0432\u043e\u0442.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0415\u0432\u0440\u043e\u0441\u043e\u044e\u0437 \u0440\u0430\u0441\u0441\u043b\u0435\u0434\u0443\u0435\u0442 \u043f\u043e\u043a\u0443\u043f\u043a\u0443 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 MMG \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 \u0432 \u0411\u0440\u0430\u0437\u0438\u043b\u0438\u0438\u000d\u000a\u0420\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440 \u043e\u043f\u0430\u0441\u0430\u0435\u0442\u0441\u044f, \u0447\u0442\u043e \u0441\u0434\u0435\u043b\u043a\u0430 \u0443\u0441\u0438\u043b\u0438\u0442 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u041a\u0438\u0442\u0430\u044f \u043d\u0430\u0434 \u043c\u0438\u0440\u043e\u0432\u044b\u043c\u0438 \u0437\u0430\u043f\u0430\u0441\u0430\u043c\u0438 \u043d\u0438\u043a\u0435\u043b\u044f.\u000d\u000a\u0415\u0432\u0440\u043e\u043a\u043e\u043c\u0438\u0441\u0441\u0438\u044f \u0440\u0430\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u0434\u0430\u0436\u0438 \u000d\u000a\u0431\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u043a\u0438\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 Anglo American \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0439 \u000d\u000aMMG \u0437\u0430 $500 \u043c\u043b\u043d. \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0434\u043e\u043b\u0436\u043d\u0430 \u000d\u000a\u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044c\u0441\u044f \u043a 20 \u043c\u0430\u0440\u0442\u0430 2026 \u0433\u043e\u0434\u0430. \u0421\u0434\u0435\u043b\u043a\u0430 \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u0440\u0443\u0434\u043d\u0438\u043a\u0438 Barro Alto \u0438 Niquelandia, \u000d\u000a\u0430 \u0442\u0430\u043a\u0436\u0435 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0449\u0438\u0435 \u0437\u0430\u0432\u043e\u0434\u044b Barro Alto \u000d\u000a\u0438 Codemin.\u000d\u000a\u043d\u0430\u0447\u0430\u043b\u0430\u000d\u000a07 09","\u041a\u0438\u0442\u0430\u0439 7\u201314 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430 \u0432\u044b\u0434\u0430\u0447\u0443 \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0439 \u000d\u000a\u043d\u0430 \u043d\u0438\u0437\u043a\u043e\u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0447\u043d\u044b\u0435 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0435 \u0437\u0430\u0432\u043e\u0434\u044b \u000d\u000a\u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043e \u043d\u0430 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432 \u0441 \u0432\u044b\u0441\u043e\u043a\u043e\u0439 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0439 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u0432\u044b\u0434\u0430\u0447\u0443 \u000d\u000a\u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0439 \u043d\u0430 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439, \u000d\u000a\u0432\u044b\u043f\u0443\u0441\u043a\u0430\u044e\u0449\u0438\u0445 \u000d\u000a\u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u043e\u000d\u000a\u043f\u0440\u043e\u043c\u0435\u0436\u0443\u0442\u043e\u0447\u043d\u044b\u0435 \u043d\u0438\u043a\u0435\u043b\u0435\u0432\u044b\u0435 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u044b \u2014 \u000d\u000a\u0447\u0435\u0440\u043d\u043e\u0432\u043e\u0439 \u0444\u0435\u0440\u0440\u043e\u043d\u0438\u043a\u0435\u043b\u044c, MHP \u0438 \u0444\u0430\u0439\u043d\u0448\u0442\u0435\u0439\u043d.\u000d\u000a#\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u044f #\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u043e\u0434\u043e\u0431\u0440\u0438\u043b \u0437\u0430\u043f\u0443\u0441\u043a \u0442\u043e\u0440\u0433\u043e\u0432 \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u0430\u043c\u0438 \u000d\u000a\u043d\u0430 \u043f\u043b\u0430\u0442\u0438\u043d\u0443 \u0438 \u043f\u0430\u043b\u043b\u0430\u0434\u0438\u0439\u000d\u000a\u041d\u043e\u0432\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u044b \u0431\u0443\u0434\u0443\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u043d\u0430 \u0424\u044c\u044e\u0447\u0435\u0440\u0441\u043d\u043e\u0439 \u0431\u0438\u0440\u0436\u0435 \u0413\u0443\u0430\u043d\u0447\u0436\u043e\u0443 (GFEX).\u000d\u000a\u041a\u043e\u043c\u0438\u0441\u0441\u0438\u044f \u043f\u043e \u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u0446\u0435\u043d\u043d\u044b\u0445 \u0431\u0443\u043c\u0430\u0433 \u000d\u000a\u041a\u0438\u0442\u0430\u044f \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044e \u0444\u044c\u044e\u0447\u0435\u0440\u0441\u043e\u0432 \u000d\u000a\u043d\u0430 \u043f\u043b\u0430\u0442\u0438\u043d\u0443 \u0438 \u043f\u0430\u043b\u043b\u0430\u0434\u0438\u0439. \u0422\u043e\u0440\u0433\u0438 \u043f\u0440\u043e\u0439\u0434\u0443\u0442 \u043d\u0430 \u0431\u0438\u0440\u0436\u0435 \u000d\u000aGFEX, \u0434\u0430\u0442\u0430 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u043d\u0435 \u0443\u0442\u043e\u0447\u043d\u044f\u0435\u0442\u0441\u044f.\u000a\u000d\u000a\u041f\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u043c \u0431\u0438\u0440\u0436\u0438, \u043f\u043b\u0430\u0442\u0438\u043d\u0430 \u0438 \u043f\u0430\u043b\u043b\u0430\u0434\u0438\u0439 \u0441\u043c\u043e\u0433\u0443\u0442 \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c\u0441\u044f \u043a\u0430\u043a \u0432 \u0441\u043b\u0438\u0442\u043a\u0430\u0445, \u0442\u0430\u043a \u0438 \u0432 \u043f\u043e\u0440\u043e\u0448\u043a\u0435. \u000d\u000a\u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0430\u000d\u000a\u0412 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u043d\u0438 \u043e\u0434\u043d\u0430 \u0434\u0440\u0443\u0433\u0430\u044f \u0431\u0438\u0440\u0436\u0430 \u000d\u000a\u0432 \u043c\u0438\u0440\u0435 \u043d\u0435 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043b\u044f\u0442\u044c \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u000d\u000a\u0432 \u043f\u043e\u0440\u043e\u0448\u043a\u0435 \u2014 \u0442\u0430\u043a\u0430\u044f \u0444\u043e\u0440\u043c\u0430 \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u0432\u044b\u0433\u043e\u0434\u043d\u0430 \u000d\u000a\u0430\u0432\u0442\u043e\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u0441\u043d\u044f\u043b \u0437\u0430\u043f\u0440\u0435\u0442 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0433\u0430\u043b\u043b\u0438\u044f, \u000d\u000a\u0433\u0435\u0440\u043c\u0430\u043d\u0438\u044f \u0438 \u0441\u0443\u0440\u044c\u043c\u044b \u0432 \u0421\u0428\u0410\u000d\u000a\u0420\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043d\u044f\u0442\u043e \u043f\u043e\u0441\u043b\u0435 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u043e\u0432 \u043c\u0435\u0436\u0434\u0443 \u0414\u043e\u043d\u0430\u043b\u044c\u0434\u043e\u043c \u0422\u0440\u0430\u043c\u043f\u043e\u043c \u0438 \u0421\u0438 \u0426\u0437\u0438\u043d\u044c\u043f\u0438\u043d\u043e\u043c.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u043a\u043e\u043c\u043c\u0435\u0440\u0446\u0438\u0438 \u041a\u0438\u0442\u0430\u044f \u000d\u000a\u043e \u043f\u0440\u0438\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0437\u0430\u043f\u0440\u0435\u0442\u0430 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u000d\u000a\u0442\u0440\u0435\u0445 \u0440\u0435\u0434\u043a\u0438\u0445 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u0432 \u0432 \u0421\u0428\u0410 \u0434\u043e \u043d\u043e\u044f\u0431\u0440\u044f \u2028\u000d\u000a2026 \u0433\u043e\u0434\u0430. \u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0431\u044b\u043b\u0438 \u0432\u0432\u0435\u0434\u0435\u043d\u044b \u000d\u000a\u0432 \u0434\u0435\u043a\u0430\u0431\u0440\u0435 2024 \u0433\u043e\u0434\u0430 \u0432 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0439 \u000d\u000a\u043e\u0431\u044a\u044f\u0432\u0438\u043b\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0430\u0434\u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u0411\u0430\u0439\u0434\u0435\u043d\u0430. \u041a\u0438\u0442\u0430\u0439 \u000d\u000a\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 90% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0433\u0430\u043b\u043b\u0438\u044f, 60% \u0433\u0435\u0440\u043c\u0430\u043d\u0438\u044f \u0438 \u043f\u043e\u0447\u0442\u0438 \u000d\u000a\u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443 \u0434\u043e\u0431\u044b\u0447\u0438 \u0441\u0443\u0440\u044c\u043c\u044b.\u000d\u000a08 09","\u041a\u0438\u0442\u0430\u0439 7\u201314 \u043d\u043e\u044f\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u043e\u0434\u043e\u0431\u0440\u0438\u043b \u0421\u041f Codelco \u0438 SQM \u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u043b\u0438\u0442\u0438\u044f \u000d\u000a\u0432 \u0427\u0438\u043b\u0438\u000d\u000a\u041e\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u0435 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0433\u043e \u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u0431\u044b\u043b\u043e \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u043c \u0443\u0441\u043b\u043e\u0432\u0438\u0435\u043c \u0434\u043b\u044f \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044f \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0433\u043e \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u043f\u043e \u0434\u043e\u0431\u044b\u0447\u0435 \u043b\u0438\u0442\u0438\u044f \u043d\u0430 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u043c \u0432 \u0427\u0438\u043b\u0438 \u0438 \u0442\u0440\u0435\u0442\u044c\u0435\u043c \u0432 \u043c\u0438\u0440\u0435 \u0441\u043e\u043b\u043e\u043d\u0447\u0430\u043a\u0435 \u0410\u0442\u0430\u043a\u0430\u043c\u0430.\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u043e\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u043f\u043e \u0440\u044b\u043d\u043e\u0447\u043d\u043e\u043c\u0443 \u043d\u0430\u0434\u0437\u043e\u0440\u0443 \u000d\u000a\u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0435 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0433\u043e \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u044f \u000d\u000a\u0447\u0438\u043b\u0438\u0439\u0441\u043a\u043e\u0439 Codelco \u0438 SQM, 22,1% \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u000d\u000a\u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0442 Tianqi Lithium. \u000a\u000d\u000a\u041e\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u0435 \u0440\u0435\u0433\u0443\u043b\u044f\u0442\u043e\u0440\u0430 \u043c\u043e\u0436\u0435\u0442 \u043e\u0437\u043d\u0430\u0447\u0430\u0442\u044c \u000d\u000a\u0441\u043c\u044f\u0433\u0447\u0435\u043d\u0438\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u043c\u0435\u0436\u0434\u0443 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u043c \u000d\u000a\u0430\u043a\u0446\u0438\u043e\u043d\u0435\u0440\u043e\u043c \u0438 \u0432\u043b\u0430\u0441\u0442\u044f\u043c\u0438 \u0427\u0438\u043b\u0438. \u0421\u0442\u043e\u0440\u043e\u043d\u044b \u000d\u000a\u043e\u0431\u044f\u0437\u0430\u043b\u0438\u0441\u044c \u043f\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0442\u044c \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044e \u000d\u000a\u043d\u0430 \u043d\u0435\u0434\u0435\u0441\u043a\u0440\u0438\u043c\u0438\u043d\u0430\u0446\u0438\u043e\u043d\u043d\u043e\u0439 \u043e\u0441\u043d\u043e\u0432\u0435 \u0438 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u000d\u000a\u0443\u0432\u0435\u0434\u043e\u043c\u043b\u044f\u0442\u044c \u043e \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f\u0445 \u000d\u000a\u0432 \u043e\u0431\u044a\u0435\u043c\u0430\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a.\u000a\u000d\u000a\u0412 2018 \u0433\u043e\u0434\u0443 Tianqi Lithium \u043f\u0440\u0438\u043e\u0431\u0440\u0435\u043b\u0430 23,77% \u000d\u000a\u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0430 \u0432 SQM \u0437\u0430 $4 \u043c\u043b\u0440\u0434. \u041a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u043c\u0435\u0436\u0434\u0443 \u000d\u000a\u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0435\u0439 \u0438 \u0432\u043b\u0430\u0441\u0442\u044f\u043c\u0438 \u0427\u0438\u043b\u0438 \u043d\u0430\u0447\u0430\u043b\u0441\u044f \u0438\u0437-\u0437\u0430 \u000d\u000a\u043d\u0435\u0443\u043f\u043b\u0430\u0442\u044b \u043d\u0430\u043b\u043e\u0433\u043e\u0432, \u0430 \u0442\u0430\u043a\u0436\u0435 \u043f\u043b\u0430\u043d\u043e\u0432 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u044e\u0436\u043d\u043e\u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u043e\u0439 \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u043e \u043b\u0438\u0442\u0438\u044f. \u000d\u000a\u043e\u0434\u043e\u0431\u0440\u0438\u043b\u043e \u000d\u000aCodelco \u043d\u0430\u043c\u0435\u0440\u0435\u0432\u0430\u043b\u0430\u0441\u044c \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u0432 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u043c \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0438 51% \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0430, \u0447\u0442\u043e \u043e\u0437\u043d\u0430\u0447\u0430\u043b\u043e \u0431\u044b \u000d\u000a\u043f\u043e\u0442\u0435\u0440\u044e SQM \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u043d\u0430\u0434 \u0434\u043e\u0431\u044b\u0447\u0435\u0439 \u043b\u0438\u0442\u0438\u044f.\u000d\u000a09 09"]